CREATE OR REPLACE FUNCTION public.restart_duel_room(p_room_id uuid, p_host_id uuid) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE v_room public.duels%ROWTYPE; v_winner jsonb; BEGIN SELECT * INTO v_room FROM public.duels WHERE id = p_room_id FOR UPDATE; IF NOT FOUND OR v_room.status <> 'finished' OR v_room.host_user_id <> p_host_id OR v_room.disbanded_at IS NOT NULL THEN RETURN false; END IF; SELECT jsonb_build_object('winner', display_name, 'date', now(), 'score', points, 'round_order', v_room.round_order, 'word_match_words', coalesce((SELECT jsonb_agg(item->>'prompt') FROM jsonb_array_elements(v_room.puzzles_public) puzzle, jsonb_array_elements(CASE WHEN puzzle->>'type' = 'wordmatch' THEN puzzle->'items' ELSE '[]'::jsonb END) item),'[]'::jsonb)) INTO v_winner FROM (SELECT p.display_name, coalesce(sum(r.score),0) points FROM public.duel_players p LEFT JOIN public.round_results r ON r.duel_id = p_room_id AND r.player_slot = p.player_slot WHERE p.duel_id = p_room_id GROUP BY p.id ORDER BY points DESC, p.player_slot LIMIT 1) ranking; DELETE FROM public.round_results WHERE duel_id = p_room_id; DELETE FROM public.duel_secrets WHERE duel_id = p_room_id; DELETE FROM public.duel_players WHERE duel_id = p_room_id AND status = 'left'; UPDATE public.duel_players SET status = 'active', ready_round = 0, intro_ready_round = 0 WHERE duel_id = p_room_id; UPDATE public.duels SET status = 'waiting', round_order = '[]'::jsonb, puzzles_public = '[]'::jsonb, current_round = 0, phase = 'intro', phase_started_at = NULL, round_started_at = NULL, tournament_history = tournament_history || coalesce(jsonb_build_array(v_winner),'[]'::jsonb) WHERE id = p_room_id; RETURN true; END; $$; REVOKE ALL ON FUNCTION public.restart_duel_room(uuid,uuid) FROM PUBLIC, anon, authenticated; GRANT EXECUTE ON FUNCTION public.restart_duel_room(uuid,uuid) TO service_role;